import string from '@adonisjs/core/helpers/string'
import { beforeCreate, type BaseModel } from '@adonisjs/lucid/orm'
import type { LucidModel, LucidRow } from '@adonisjs/lucid/types/model'
import type { NormalizeConstructor } from '@adonisjs/core/types/helpers'

/**
 * Mixin for models whose primary key is a UUID generated by the
 * application, so the id is known before the row is inserted.
 *
 * Declare the key column as `table.uuid('id').primary()` in the migration,
 * then compose the mixin into the model:
 *
 * @example
 * export default class Post extends compose(PostSchema, withUuidPrimaryKey()) {}
 */
export function withUuidPrimaryKey() {
  return <Model extends NormalizeConstructor<typeof BaseModel>>(superclass: Model) => {
    class WithUuidPrimaryKey extends superclass {
      /**
       * Tell Lucid the primary key is set by the application instead of
       * being read back from the database after the insert
       */
      static selfAssignPrimaryKey = true

      /**
       * Assign a UUID unless one was set explicitly, e.g. by a seeder
       */
      @beforeCreate()
      static assignUuid(model: LucidRow) {
        const primaryKey = (model.constructor as LucidModel).primaryKey

        if (!model.$attributes[primaryKey]) {
          model.$attributes[primaryKey] = string.uuid()
        }
      }
    }

    return WithUuidPrimaryKey
  }
}
